"""Larger-scale differential fuzzing: wide fanout, deep branches, big backlogs."""
import json
import random
import sys

sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/tests')

from utils import run_request as fast
from reference import Ref


def borders(rng, U, maxranges=8):
    n = rng.randint(1, min(maxranges, max(1, U - 1)))
    pts = sorted(rng.sample(range(1, U), n)) if U > 1 and n else []
    return [0] + pts + [U]


def make_run(rng, profile):
    M = rng.randint(1, 16 if profile == 'wide' else 4)
    L = rng.randint(1, 8 if profile == 'wide' else 3)
    U = rng.choice([1, 2, 7, 40, 1000, 2147483647])
    kind = rng.choice(['fifo', 'sp', 'sff', 'wfq'])
    flows = rng.sample(range(0, 40), rng.randint(1, 12))
    if kind == 'fifo':
        policy = {'kind': 'fifo'}
    elif kind == 'sff':
        policy = {'kind': 'sff'}
    elif kind == 'sp':
        policy = {'kind': 'sp', 'levels': [[f, rng.randint(0, U)] for f in flows]}
    else:
        policy = {'kind': 'wfq', 'weights': [[f, rng.randint(1, 1024)] for f in flows]}
    if profile == 'deep':
        fifo = rng.choice([8, 64, 10 ** 6])
        pifo = rng.choice([1, 3, 8, 64, 10 ** 6])
        batch = rng.randint(1, 32)
        period = rng.choice([1, 2, 7, 100000])
        count = rng.randint(50, 400)
    else:
        fifo = rng.choice([16, 1000, 10 ** 7])
        pifo = rng.choice([1, 16, 1000, 10 ** 7])
        batch = rng.randint(1, 32)
        period = rng.choice([1, 3, 11, 100000])
        count = rng.randint(50, 300)
    ids = rng.sample(range(0, 10 ** 6), count)
    events = []
    saves = []
    seen = []
    for _ in range(count):
        c = rng.random()
        if c < 0.45 and ids:
            pid = ids.pop()
            events.append(['enqueue', pid, rng.choice(flows), rng.randint(1, 40), rng.randint(0, U)])
            seen.append(pid)
        elif c < 0.65:
            events.append(['dequeue', rng.randint(1, 6)])
        elif c < 0.70:
            events.append(['sample'])
        elif c < 0.76:
            events.append(['repartition', borders(rng, U, 12)])
        elif c < 0.83 and seen:
            events.append(['cancel', rng.choice(seen)])
        elif c < 0.88 and seen:
            events.append(['inspect', rng.choice(seen)])
        elif c < 0.90 and kind == 'wfq':
            events.append(['weight', rng.choice(flows), rng.randint(1, 1024)])
        elif c < 0.96:
            name = rng.randint(0, 7)
            events.append(['save', name])
            saves.append(name)
        elif saves:
            events.append(['restore', rng.choice(saves)])
        else:
            name = rng.randint(0, 7)
            events.append(['save', name])
            saves.append(name)
    for _ in range(rng.randint(0, 5)):
        events.append([rng.choice(['cancel', 'inspect']), rng.randint(10 ** 7, 10 ** 7 + 50)])
    return {'banks': M, 'load_balancers': L, 'fifo_bytes': fifo, 'pifo_bytes': pifo,
            'refill_batch': batch, 'sample_period': period,
            'borders': borders(rng, U, 12), 'policy': policy, 'events': events}


def main():
    profile = sys.argv[1] if len(sys.argv) > 1 else 'deep'
    cases = int(sys.argv[2]) if len(sys.argv) > 2 else 25
    seed = int(sys.argv[3]) if len(sys.argv) > 3 else 1
    rng = random.Random(seed)
    bad = 0
    for case in range(cases):
        runs = [make_run(rng, profile)]
        request = {'runs': runs}
        expected = {'runs': [Ref(cfg).run(cfg['events']) for cfg in runs]}
        actual = fast(json.loads(json.dumps(request)))
        if actual != expected:
            bad += 1
            print('MISMATCH', profile, 'case', case)
            a, e = actual['runs'][0], expected['runs'][0]
            for x, y in zip(a['log'], e['log']):
                if x != y:
                    print('  first log diff\n   got', x, '\n   exp', y)
                    break
            else:
                if len(a['log']) != len(e['log']):
                    print('  log length', len(a['log']), len(e['log']))
                    print('  got tail', a['log'][len(e['log']):][:3])
                    print('  exp tail', e['log'][len(a['log']):][:3])
                for key in e['state']:
                    if a['state'].get(key) != e['state'][key]:
                        print('  state diff', key, '\n   got', a['state'].get(key), '\n   exp', e['state'][key])
            with open('/workspace/tests/fail2_%s_%d_%d.json' % (profile, seed, case), 'w') as fh:
                json.dump(request, fh, indent=1)
            if bad >= 2:
                break
    print('profile %s: checked %d cases, %d mismatches' % (profile, case + 1, bad))
    return 1 if bad else 0


if __name__ == '__main__':
    sys.exit(main())
